Definition long_hdr_b (alloc size A : Z) : list cell :=
  [C1 (b8 ((alloc + 1) mod 256)); CB 7 (Z_to_le_bytes 7 (Z.shiftr (alloc + 1) 8)); C8 (wz size); C8 (wz A)].

Lemma b8_mod256 : forall z, b8 (z mod 256) = b8 z.
Proof. intros z. unfold b8. apply bv_eq. rewrite !Z_to_bv_unsigned, !bv_wrap8_mod. change (2^8) with 256. rewrite Z.mod_mod by lia. reflexivity. Qed.

Lemma le8_wz_cons : forall z, 0 <= z < 2^64 -> le8 (wz z) = b8 (z mod 256) :: Z_to_le_bytes 7 (Z.shiftr z 8).
Proof.
  intros z Hz. unfold le8, word_to_le_bytes, wz. rewrite unsigned_lit by lia. cbn [Z_to_le_bytes].
  f_equal. symmetry. apply b8_mod256.
Qed.

Lemma long_hdr_byteview : forall m a alloc size A, 0 <= alloc + 1 < 2^64 ->
