Lemma short_assemble : forall LB m a (n : Z) bs rest,
  rw_cells usegs m a [C1 (b8 (2 * n))] -> rw_cells usegs m (a + 1) [CB (Z.to_nat n) bs] ->
  rw_cells usegs m (a + 1 + n) [C1 (b8 0); CB (Z.to_nat (22 - n)) rest] ->
  0 <= n <= 22 -> length bs = Z.to_nat n ->
  StrObj LB m a (mkS bs None).
Proof.
  intros LB m a n bs rest H0 H1 H2 Hn L.
  apply (StrObj_short_intro LB m a bs rest); [unfold zlength; lia|].
  unfold short_cells, zlength. rewrite L. replace (Z.of_nat (Z.to_nat n)) with n by lia.
  replace (22 - Z.to_nat n)%nat with (Z.to_nat (22 - n)) by lia.
  change (C1 (b8 (2 * n)) :: CB (Z.to_nat n) bs :: [C1 (b8 0); CB (Z.to_nat (22 - n)) rest])
    with ([C1 (b8 (2 * n))] ++ (CB (Z.to_nat n) bs :: [C1 (b8 0); CB (Z.to_nat (22 - n)) rest])).
  apply rw_cells_app. cbn [cells_size csize Nat.add]. split; [exact H0|].
  apply (rw_cells_uncut _ _ _ _ _ H1). replace (a + 1 + Z.of_nat (Z.to_nat n)) with (a + 1 + n) by lia. exact H2.
Qed.

